html:
{#- Candidate Interview Evaluation / Score Form, LPL/HR/17 Rev 1, laid out like the
    paper form: one panel member's sheet. The criteria and their order come from the
    sheet itself (Interview Feedback Score rows), the salary history from the Job
    Applicant, recorded once for every panel member. -#}
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro money(value, currency) -%}{{ frappe.utils.fmt_money(value, currency=currency) if value else "" }}{%- endmacro -%}
{%- set logo = frappe.db.get_single_value("HRMS Addon Branding", "company_logo") -%}
{%- set applicant = frappe.db.get_value("Job Applicant", doc.job_applicant,
    ["applicant_name", "phone_number", "email_id", "designation", "currency", "custom_previous_salary",
     "custom_current_benefits", "lower_range", "upper_range", "custom_expected_benefits", "custom_notice_period"],
    as_dict=True) if doc.job_applicant else none -%}
{%- set applicant = applicant or {} -%}
{%- set interview = frappe.db.get_value("Interview", doc.interview, ["scheduled_on", "designation"], as_dict=True) if doc.interview else none -%}
{%- set interview = interview or {} -%}
{%- set position = applicant.designation or interview.designation or "" -%}
{%- set contact = [applicant.phone_number, applicant.email_id] | select | join(", ") -%}
{%- set low = money(applicant.lower_range, applicant.currency) -%}
{%- set high = money(applicant.upper_range, applicant.currency) -%}
{%- set scores = ["1", "2", "3", "4", "5", "N/A"] -%}
{%- set rows = doc.custom_scores or [] -%}
<style>
	.lpl-score { font-family: Arial, Helvetica, sans-serif; font-size: 10.5px; color: #000; }
	.lpl-score table { width: 100%; border-collapse: collapse; margin: 0 0 8px; }
	.lpl-score tr { page-break-inside: avoid; }
	.lpl-score td, .lpl-score th { border: 1px solid #555; padding: 4px 6px; vertical-align: top; text-align: left; }
	.lpl-score th, .lpl-score td.lbl { font-weight: bold; }
	.lpl-score .head td { vertical-align: middle; }
	.lpl-score .head .title { text-align: center; font-weight: bold; }
	.lpl-score .group td { font-weight: bold; background: #f2f2f2; }
	.lpl-score .num { width: 5.5%; text-align: center; }
	.lpl-score .tick { text-align: center; font-family: "DejaVu Sans", Arial, sans-serif; font-weight: bold; }
	.lpl-score .legend { margin: 6px 0 8px; }
	.lpl-score .box { display: inline-block; width: 12px; height: 12px; border: 1px solid #000; margin-right: 6px;
		vertical-align: middle; text-align: center; line-height: 11px; font-family: "DejaVu Sans", Arial, sans-serif; }
</style>
<div class="lpl-score">
	<table class="head">
		<tr>
			<td rowspan="3" style="width: 18%; text-align: center">
				{%- if logo %}<img src="{{ logo }}" style="max-width: 100%; max-height: 56px">{% endif -%}
			</td>
			<td rowspan="3" class="title" style="width: 48%">LUUKA PLASTICS LIMITED</td>
			<td style="width: 18%">Doc Ref. No:</td>
			<td>LPL/HR/17</td>
		</tr>
		<tr><td>Initial Issue Date</td><td>14/03/2017</td></tr>
		<tr><td>Revision Date:</td><td>25/01/2021</td></tr>
		<tr>
			<td colspan="2" class="title">CANDIDATE INTERVIEW EVALUATION /SCORE FORM</td>
			<td>Revision No.</td>
			<td>1</td>
		</tr>
	</table>

	<table>
		<tr>
			<td style="width: 50%"><b>Name of Candidate:</b> {{ v(applicant.applicant_name) }}</td>
			<td><b>Interviewer Name:</b> {{ v(frappe.db.get_value("User", doc.interviewer, "full_name") or doc.interviewer) }}</td>
		</tr>
		<tr>
			<td><b>Position:</b> {{ v(position) }}</td>
			<td><b>Interviewer Designation:</b> {{ v(doc.custom_interviewer_designation) }}</td>
		</tr>
		<tr>
			<td><b>Applicant's Contact:</b> {{ v(contact) }}</td>
			<td><b>Interview Date:</b> {{ frappe.utils.format_date(interview.scheduled_on) if interview.scheduled_on else "" }}</td>
		</tr>
	</table>

	<p class="legend"><b><u>Score Rating:</u></b> Excellent=5 (90-100%), Very Good=4 (75-89%), Good=3 (60-74%),
		Average=2 (50-59%), Below Average=1 (49% and below)</p>

	<table>
		<tr>
			<th style="width: 27%">Job Requirements</th>
			<th style="width: 40%; text-align: center">Interviewer's Comments</th>
			<th colspan="6" style="text-align: center">Scores Rating</th>
		</tr>
		<tr>
			<th colspan="2"></th>
			{%- for score in scores %}<th class="num">{{ score }}</th>{% endfor %}
		</tr>
		{%- set ns = namespace(group=None) %}
		{%- for row in rows %}
			{%- set group_rows = rows | selectattr("criteria_group", "equalto", row.criteria_group) | list %}
			{%- set single = group_rows | length == 1 and (row.criteria_group or "") | lower == (row.criterion or "") | lower %}
			{%- if row.criteria_group != ns.group and not single %}
		<tr class="group"><td colspan="8">{{ v(row.criteria_group) }}:</td></tr>
			{%- endif %}
			{%- set ns.group = row.criteria_group %}
		<tr>
			<td{% if single %} class="lbl"{% endif %}>{{ v(row.criterion) }}{% if single %}:{% endif %}</td>
			<td>{{ v(row.comments) | replace("\n", "<br>") }}</td>
			{%- for score in scores %}
			<td class="num tick">{% if (row.score or "") == score %}&#10003;{% endif %}</td>
			{%- endfor %}
		</tr>
		{%- endfor %}
		<tr>
			<td colspan="2" class="lbl">Total Score:
				{%- if doc.custom_max_score %} {{ doc.custom_total_score }} of {{ doc.custom_max_score }}
				({{ frappe.utils.flt(doc.custom_score_percent, 2) }}%, {{ v(doc.custom_score_band) }}){% endif %}</td>
			{%- for score in scores %}
			{%- set count = rows | selectattr("score", "equalto", score) | list | length %}
			<td class="num">{{ count if count else "" }}</td>
			{%- endfor %}
		</tr>
	</table>

	<table>
		<tr><td colspan="2" class="lbl">Salary History &amp; Expectation:</td></tr>
		<tr><td style="width: 27%">Current Salary</td><td>{{ money(applicant.custom_previous_salary, applicant.currency) }}</td></tr>
		<tr><td>Benefits</td><td>{{ v(applicant.custom_current_benefits) | replace("\n", "<br>") }}</td></tr>
		<tr><td>Salary Expectation</td><td>{{ (low ~ " - " ~ high) if (low and high) else (low or high) }}</td></tr>
		<tr><td>Benefits</td><td>{{ v(applicant.custom_expected_benefits) | replace("\n", "<br>") }}</td></tr>
		<tr><td>Notice period</td><td>{{ v(applicant.custom_notice_period) }}</td></tr>
		<tr>
			<td colspan="2" style="height: 90px">
				<b>Interviewer's comments on suitability of the candidate in regard to the position (Brief notes about the candidate):</b><br>
				{{ v(doc.feedback) | replace("\n", "<br>") }}
			</td>
		</tr>
	</table>

	<table>
		<tr><td colspan="3" class="lbl">Recommendation:</td></tr>
		<tr>
			{%- for option in ["Offer", "Shortlist", "Reject"] %}
			<td style="width: 33%"><span class="box">{% if doc.custom_recommendation == option %}&#10003;{% endif %}</span>{{ option }}</td>
			{%- endfor %}
		</tr>
	</table>
	<p><b><u>Meaning of recommendation, Offer</u>=Selected, <u>Shortlist</u>=to be interviewed again, <u>Reject</u>=Not selected</b></p>
	<p style="margin-top: 22px"><b>Signature of interviewer</b> ................................................
		<b>Date</b> {{ frappe.utils.format_date(doc.modified) if doc.docstatus == 1 else "............................" }}</p>
</div>
